/**
 * Creates the booking(s) needed for cart construction.
 *
 * Branches on the service selection:
 * - DAY-range path with 1 picked day     -> `createBooking`
 * - DAY-range path with `allDay`         -> `createBooking` (one combined Booking)
 * - DAY-range path with 2..8 picked days -> `createMultiServiceBooking`
 * - default path                         -> `createBooking`
 *
 * All branches return the same shape so `executeBookAction` can stay
 * branchless from cart-creation onwards. Cart construction reads each
 * single-service booking ID — per SDK guidance, never the
 * `multiServiceBooking._id`.
 */
import { createBooking } from '../../../api/create-booking/index.js';
import { createMultiServiceBooking } from '../../../api/create-multi-service-booking/index.js';
import { buildBookingRequest } from './buildBookingRequest.js';
import { buildDayRangeBookingRequest } from './buildDayRangeBookingRequest.js';
import { isDayRangeService } from './dayRange.js';
export async function createBookingsForCart(params) {
    const firstSelection = params.serviceSelections[0];
    if (!firstSelection) {
        throw new Error('No service selection provided');
    }
    if (isDayRangeService(firstSelection.service)) {
        const req = buildDayRangeBookingRequest(params);
        if (req.bookings.length === 1) {
            const bookingResponse = await createBooking(req.bookings[0], {
                participantNotification: req.participantNotification,
                sendSmsReminder: req.sendSmsReminder,
                formSubmission: req.formSubmission,
            });
            const bookingId = bookingResponse.booking?._id;
            return {
                bookingIds: bookingId ? [bookingId] : [],
                contactDetails: bookingResponse.booking?.contactDetails,
            };
        }
        const response = await createMultiServiceBooking(req.bookings, {
            participantNotification: req.participantNotification,
            sendSmsReminder: req.sendSmsReminder,
            formSubmission: req.formSubmission,
        });
        const bookings = response.multiServiceBooking?.bookings ?? [];
        return {
            bookingIds: bookings
                .map((b) => b.booking?._id)
                .filter(Boolean),
            contactDetails: bookings[0]?.booking?.contactDetails,
        };
    }
    const createBookingRequest = buildBookingRequest(params);
    const bookingResponse = await createBooking(createBookingRequest.booking, {
        participantNotification: createBookingRequest.participantNotification,
        sendSmsReminder: createBookingRequest.sendSmsReminder,
        formSubmission: createBookingRequest.formSubmission,
    });
    const bookingId = bookingResponse.booking?._id;
    return {
        bookingIds: bookingId ? [bookingId] : [],
        contactDetails: bookingResponse.booking?.contactDetails,
    };
}
